import fs from 'node:fs';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';
const root='reports/local/g03-growth-consumption-20261023',read=p=>JSON.parse(fs.readFileSync(p,'utf8')),plan=read(root+'/plan.json'),sha=p=>createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const repaired=process.argv[2]==='repaired',outputName=repaired?'summary-final-live':'summary-live';
const sum=(rows,key)=>rows.reduce((n,r)=>n+(r[key]??0),0),round=n=>Math.round(n*100)/100;
const rows=[],missing=[];
for(const c of plan.cases){
 const id=[c.version,c.policy,c.race,c.difficulty,c.tier,c.seed].join('-'),file=root+'/'+(repaired&&c.policy==='spending'?'repaired-routes':'routes')+'/'+id+'.json';if(!fs.existsSync(file)||fs.existsSync(file+'.lock')){missing.push(id);continue;}
 const d=read(file);assert.equal(d.id,id);for(const k of ['race','difficulty','tier','seed','version','policy'])assert.equal(d[k],c[k]);
 for(const [p,h] of Object.entries(d.runtimeBinding.tools))assert.equal(sha(p),h,id+': tool binding '+p);assert.equal(sha(d.runtimeBinding.sourceManifest),d.runtimeBinding.sourceManifestSha256);
 const e=d.policyDetails.events,modern=c.policy==='spending',purchases=e.filter(e=>e.kind==='shop-purchase'&&e.data.ok),dev=e.filter(e=>e.kind===(modern?'development-purchase':'development')&&e.data.ok),repair=e.filter(e=>e.kind==='repair'&&e.data.ok),revives=e.filter(e=>e.kind===(modern?'hero-revive':'revive')&&e.data.ok),refresh=e.filter(e=>e.kind==='shop-refresh');
 const types=purchases.reduce((o,e)=>(o[e.data.offer.expeditionEffect.kind]=(o[e.data.offer.expeditionEffect.kind]??0)+1,o),{});
 const gear=a=>Object.entries(a.equipped[c.race]).filter(([slot])=>/^(offense|defense)/.test(slot)).map(([slot,id])=>({slot,id,quality:a.items[id].quality,template:a.items[id].template,pollution:a.items[id].pollution}));
 const stages=d.stages.filter(s=>s.phase==='reward').map(s=>({stage:s.stage,wallet:s.wallet,purchases:s.economy.purchases,production:s.economy.production,refresh:s.economy.rerolls,heroes:s.heroes.map(h=>({id:h.id,rank:h.rank})),ordinary:s.allies.filter(u=>!u.hero&&!u.elite).length,elites:s.allies.filter(u=>u.elite).length,training:e.filter(e=>e.stage===s.stage&&e.kind==='shop-purchase'&&e.data.ok&&e.data.offer.expeditionEffect.kind==='training').length}));
 rows.push({id,...c,file,sha256:sha(file),stop:d.stop,stage:d.stage,notice:d.final.notice,issue:d.issue,wallSeconds:d.wallSeconds,time:d.time,steps:d.steps,deaths:d.deathRows.length,deathKinds:d.deathRows.reduce((o,u)=>(o[u.hero?'hero':u.elite?'elite':'ordinary']++,o),{ordinary:0,hero:0,elite:0}),intermissions:stages.length,development:dev.length,shop:modern?{purchases:purchases.length,types,paidQuotePurchases:purchases.filter(e=>e.data.price.minerals+e.data.price.gas>0).length,firstFree:purchases.filter(e=>e.data.price.firstFree).length,refreshes:refresh.length,paidRefreshes:refresh.filter(e=>e.data.cost>0).length,refreshMinerals:sum(refresh.map(e=>e.data),'cost'),stopReasons:e.filter(e=>e.kind==='shop-stop').reduce((o,e)=>(o[e.data.reason]=(o[e.data.reason]??0)+1,o),{})}:{reportedActions:e.filter(e=>e.kind==='shop').length,note:'Legacy controller logs accepted shop actions, which can include a later canceled family replacement. Do not label these all completed purchases.'},repair:{count:repair.length,minerals:sum(repair.map(e=>e.data.quote),'minerals'),gas:sum(repair.map(e=>e.data.quote),'gas')},heroRevives:revives.length,wallet:{minerals:round(d.final.wallet.minerals),gas:round(d.final.wallet.gas)},nativeEconomy:d.final.economy,heroes:d.final.heroes.map(h=>({id:h.id,rank:h.rank})),allies:d.final.allies.map(u=>({id:u.id,type:u.type,rank:u.rank,hero:u.hero,elite:u.elite,hp:u.hp,maxHp:u.maxHp})),initialGear:gear(d.opening),finalGear:gear(d.finalAccount),gearSwaps:e.filter(e=>e.kind==='equip'),outsideCrossing:d.specials.filter(s=>s.kind==='crossing'&&s.outside.length),specials:d.specials.map(s=>({stage:s.stage,kind:s.kind,participants:s.participants.length})),reconciliation:d.economyAudit.reconciliation,stages});
}
const counts=rs=>({total:rs.length,entered:rs.filter(r=>r.stop==='entered-endless').length,lost:rs.filter(r=>r.stop==='lost').length,censored:rs.filter(r=>['wall-censored','step-censored'].includes(r.stop)).length,errors:rs.filter(r=>r.stop==='error').length});
const groups=[];for(const version of ['before','after'])for(const policy of ['legacy','spending'])for(const difficulty of ['easy','normal','hard','hell'])for(const tier of ['entry','graduation','polluted']){const rs=rows.filter(r=>r.version===version&&r.policy===policy&&r.difficulty===difficulty&&r.tier===tier);if(rs.length)groups.push({version,policy,difficulty,tier,...counts(rs),deaths:sum(rs,'deaths'),development:sum(rs,'development'),shopPurchases:policy==='spending'?sum(rs.map(r=>r.shop),'purchases'):null,reportedLegacyShopActions:policy==='legacy'?sum(rs.map(r=>r.shop),'reportedActions'):null,nativePurchaseMinerals:round(sum(rs.map(r=>r.nativeEconomy.purchases),'minerals')),nativePurchaseGas:round(sum(rs.map(r=>r.nativeEconomy.purchases),'gas')),nativeProductionMinerals:round(sum(rs.map(r=>r.nativeEconomy.production),'minerals')),nativeProductionGas:round(sum(rs.map(r=>r.nativeEconomy.production),'gas')),nativeRefreshMinerals:round(sum(rs.map(r=>({minerals:r.nativeEconomy.rerolls})),'minerals'))});}
const pairs=[];for(const race of ['terran','zerg','protoss'])for(const difficulty of ['hard','hell'])for(const tier of ['entry','graduation']){
 const rs=rows.filter(r=>r.race===race&&r.difficulty===difficulty&&r.tier===tier&&r.seed===529);
 const lastRewards=rs.map(r=>Math.max(0,...r.stages.map(s=>Number(s.stage.split(':')[1]))));
 pairs.push({race,difficulty,tier,arms:rs.map(r=>({id:r.id,version:r.version,policy:r.policy,stop:r.stop,stage:r.stage,purchases:r.nativeEconomy.purchases,production:r.nativeEconomy.production,refresh:r.nativeEconomy.rerolls,wallet:r.wallet,deaths:r.deaths,development:r.development,heroes:r.heroes})),commonRewardStage:rs.length===3?Math.min(...lastRewards):null});
}
const lossNotices=rows.filter(r=>r.stop==='lost').reduce((out,r)=>{out[r.notice]=(out[r.notice]??0)+1;return out;},{});
const output={date:'2026-10-23',cohort:repaired?'12 original legacy rows plus 45 repair-selection corrected spending replays':'57 original routes; spending repair eligibility defect retained',complete:rows.length===plan.cases.length,planned:plan.cases.length,count:rows.length,missing,counts:counts(rows),lossNotices,groups,pairs,rows};
fs.writeFileSync(root+'/'+outputName+'.json',JSON.stringify(output,null,2)+'\n');console.log(JSON.stringify({complete:output.complete,count:rows.length,missing:missing.length,counts:output.counts,groups},null,2));
